1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type { SceneObjectContext } from "../../types/engine.types.js";
4	import type {
5	  GravityBallsObjectOptions,
6	  GravityBallsTweenProps,
7	  SmokeFloorRuntime,
8	} from "../../types/object.types.js";
9	
10	interface SphereInfo {
11	  ID: number;
12	  startX: number;
13	  startY: number;
14	  startZ: number;
15	  spawnX: number;
16	  spawnY: number;
17	  vx: number;
18	  vy: number;
19	  vz: number;
20	  gravity: number;
21	  rotDir: number;
22	  shrinkRate: number;
23	  initScale: number;
24	  bounced: boolean;
25	  vxMult: number;
26	  vzMult: number;
27	  vyMult: number;
28	  sphere: THREE.Sprite;
29	  material: THREE.SpriteMaterial;
30	}
31	
32	type ResolvedOpts = {
33	  attachTo: string;
34	  spawnOffset: { x?: number; y?: number; z?: number };
35	  colors: string[];
36	  dotsPerInterval: number;
37	  physicsScale: number;
38	  proximityRange: number;
39	  maxGravityBoost: number;
40	  vxMult: number;
41	  vzMult: number;
42	  vyMult: number;
43	  particleScaleMin: number;
44	  particleScaleMax: number;
45	};
46	
47	const FADE_START_SCALE = 0.65;
48	const SMOKE_Z_DRIFT = 0.002;
49	const SMOKE_SPREAD = 1.005;
50	const DEFAULT_PARTICLE_SCALE_MIN = 1.2;
51	const DEFAULT_PARTICLE_SCALE_MAX = 3.0;
52	const LIFETIME_TICKS = 150;
53	const SMOKE_FLOOR_RUNTIME_KEY = "smokeFloor.runtime";
54	
55	const DEFAULT_TEXTURE_URLS = [
56	  "/resource/images/texture/smoke/smoke_01.png",
57	  "/resource/images/texture/rocket/smoke.png",
58	];
59	
60	const DEFAULTS = {
61	  attachTo: "rocket",
62	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
63	  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
64	  dotsPerInterval: 3,
65	  physicsScale: 0.006,
66	  proximityRange: 4.0,
67	  maxGravityBoost: 3.0,
68	  vxMult: 2.5,
69	  vzMult: 1.5,
70	  vyMult: -0.5,
71	  gravityBase: 10,
72	  floorLevel: -2.5,
73	  floorDimensions: 25,
74	};
75	
76	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
77	  private readonly _balls = new Map<number, SphereInfo>();
78	  private _idx = 0;
79	  private _accumMs = 0;
80	  private readonly _spawnPt = new THREE.Vector3();
81	  private _opts: GravityBallsObjectOptions = {};
82	  private _baseMats: THREE.SpriteMaterial[] = [];
83	
84	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
85	    if (props) this._opts = { ...this._opts, ...props };
86	    return this;
87	  }
88	
89	  protected override getOptions(): Record<string, unknown> {
90	    return this._opts as Record<string, unknown>;
91	  }
92	
93	  override async runObject(): Promise<void> {
94	    const ctx = this._context;
95	    if (!ctx) return;
96	
97	    const urls: string[] =
98	      this._opts.textureUrls?.length ? this._opts.textureUrls
99	      : this._opts.textureUrl ? [this._opts.textureUrl]
100	      : DEFAULT_TEXTURE_URLS;
101	
102	    const textures = await Promise.all(
103	      urls.map(async (url): Promise<THREE.Texture | null> => {
104	        if (!url || !ctx.loadTexture) return null;
105	        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
106	        catch { return null; }
107	      }),
108	    );
109	
110	    this._baseMats = textures.length > 0
111	      ? textures.map(tex => new THREE.SpriteMaterial({
112	          map: tex ?? null,
113	          transparent: true,
114	          depthWrite: false,
115	          opacity: 0.8,
116	        }))
117	      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];
118	
119	    this._applyOptionVisibility();
120	  }
121	
122	  override runUpdate(delta: number): void {
123	    const ctx = this._context;
124	    if (!ctx || this._disposed || !this.getVisibleState()) return;
125	
126	    this._accumMs += delta * 1000;
127	    if (this._accumMs >= 15) {
128	      this._accumMs -= 15;
129	      this._tick(ctx);
130	    }
131	  }
132	
133	  private _getFloorRuntime(): SmokeFloorRuntime | null {
134	    const candidate = this._context?.getObject(SMOKE_FLOOR_RUNTIME_KEY);
135	    if (candidate && typeof (candidate as unknown as SmokeFloorRuntime).getFloorY === "function") {
136	      return candidate as unknown as SmokeFloorRuntime;
137	    }
138	    return null;
139	  }
140	
141	  private _computeGravityScale(rocketY: number, floorY: number, o: ResolvedOpts): number {
142	    const dist = Math.max(0, rocketY - floorY);
143	    const t = 1 - Math.min(1, dist / o.proximityRange);
144	    return 1 + t * o.maxGravityBoost;
145	  }
146	
147	  private _tick(ctx: SceneObjectContext): void {
148	    const o = this._resolve();
149	
150	    if (o.attachTo) {
151	      const rkt = ctx.getObject(o.attachTo);
152	      if (rkt instanceof THREE.Object3D) {
153	        rkt.getWorldPosition(this._spawnPt);
154	        this._spawnPt.x += o.spawnOffset.x ?? 0;
155	        this._spawnPt.y += o.spawnOffset.y ?? 0;
156	        this._spawnPt.z += o.spawnOffset.z ?? 0;
157	      }
158	    }
159	
160	    const floorRuntime = this._getFloorRuntime();
161	    const floorY = floorRuntime?.getFloorY() ?? (this._opts.floorLevel ?? DEFAULTS.floorLevel);
162	    const floorDim = floorRuntime?.getFloorDimensions() ?? (this._opts.floorDimensions ?? DEFAULTS.floorDimensions);
163	    const gravityScale = this._computeGravityScale(this._spawnPt.y, floorY, o);
164	
165	    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o, gravityScale);
166	
167	    const dead: number[] = [];
168	    this._balls.forEach((b, id) => { if (this._step(b, floorY, floorDim)) dead.push(id); });
169	    for (const id of dead) this._balls.delete(id);
170	  }
171	
172	  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts, gravityScale: number): void {
173	    if (this._baseMats.length === 0) return;
174	
175	    const s = o.physicsScale;
176	    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
177	    const mat = baseMat.clone();
178	
179	    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
180	    mat.color.set(color);
181	    mat.rotation = Math.random() * Math.PI * 2;
182	
183	    const initScale = o.particleScaleMin + Math.random() * (o.particleScaleMax - o.particleScaleMin);
184	    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;
185	
186	    const isXNeg = this._rnd(0, 2) === 0;
187	    const isZNeg = this._rnd(0, 2) === 0;
188	
189	    const sprite = new THREE.Sprite(mat);
190	    sprite.scale.setScalar(initScale);
191	
192	    const info: SphereInfo = {
193	      ID: ++this._idx,
194	      startX: this._spawnPt.x,
195	      startY: this._spawnPt.y,
196	      startZ: this._spawnPt.z,
197	      spawnX: this._spawnPt.x,
198	      spawnY: this._spawnPt.y,
199	      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
200	      vy: this._rnd(-10, 10) * s,
201	      vz: isZNeg ? this._rnd(1, 26) * -0.4 * s : this._rnd(1, 26) * 0.4 * s,
202	      gravity: DEFAULTS.gravityBase * s * gravityScale,
203	      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
204	      shrinkRate,
205	      initScale,
206	      bounced: false,
207	      vxMult: o.vxMult,
208	      vzMult: o.vzMult,
209	      vyMult: o.vyMult,
210	      sphere: sprite,
211	      material: mat,
212	    };
213	
214	    ctx.scene.add(sprite);
215	    this._balls.set(info.ID, info);
216	  }
217	
218	  private _step(b: SphereInfo, floorY: number, floorDim: number): boolean {
219	    const sp = b.sphere;
220	
221	    sp.scale.x += b.shrinkRate;
222	    sp.scale.y += b.shrinkRate;
223	
224	    b.startX += b.vx * 0.6;
225	    b.startY -= b.vy * 0.5;
226	    b.startZ -= b.vz * 0.6;
227	    sp.position.x = b.startX;
228	    sp.position.y = b.startY;
229	    sp.position.z = b.startZ;
230	
231	    b.vy += b.gravity;
232	    b.material.rotation += b.rotDir;
233	
234	    const bounceY = floorY + sp.scale.x * 0.5;
235	    if (sp.position.y < bounceY) {
236	      sp.position.y = bounceY;
237	      b.startY = bounceY;
238	
239	      const inBounds =
240	        Math.abs(sp.position.x) < floorDim / 2 &&
241	        Math.abs(sp.position.z) < floorDim / 2;
242	
243	      if (!b.bounced) {
244	        b.vx *= b.vxMult;
245	        b.vz *= b.vzMult;
246	        if (inBounds) b.vy *= b.vyMult;
247	        b.bounced = true;
248	      } else {
249	        b.vx *= 0.92;
250	        b.vz *= 0.92;
251	        if (inBounds) b.vy *= b.vyMult;
252	      }
253	    }
254	
255	    if (sp.scale.y < FADE_START_SCALE) {
256	      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
257	      sp.position.z -= SMOKE_Z_DRIFT;
258	      const dx = b.startX - b.spawnX;
259	      const dy = b.startY - b.spawnY;
260	      b.startX = b.spawnX + dx * SMOKE_SPREAD;
261	      b.startY = b.spawnY + dy * SMOKE_SPREAD;
262	    }
263	
264	    if (sp.scale.y <= 0.1) {
265	      this._context?.scene.remove(sp);
266	      b.material.dispose();
267	      return true;
268	    }
269	    return false;
270	  }
271	
272	  protected override applyVisibility(visible: boolean): void {
273	    if (!visible) {
274	      const scene = this._context?.scene;
275	      this._balls.forEach(b => {
276	        scene?.remove(b.sphere);
277	        b.material.dispose();
278	      });
279	      this._balls.clear();
280	    }
281	  }
282	
283	  override dispose(): void {
284	    if (this._disposed) return;
285	    const scene = this._context?.scene;
286	
287	    this._balls.forEach(b => {
288	      scene?.remove(b.sphere);
289	      b.material.dispose();
290	    });
