import type { GSAPTimeline } from "../types/gsap.types.js";
import type { IntroRunContext } from "../types/core.types.js";

const INTRO_PANEL_SELECTOR = "#intro-card";
const INTRO_PERCENT_SELECTOR = "#pct-text";
const INTRO_PROGRESS_HOLD_MAX = 96;
const INTRO_PROGRESS_STEP_MIN = 0.1;
const INTRO_PROGRESS_EASE = 0.028;
const INTRO_PROGRESS_MIN_DURATION_MS = 2200;
const INTRO_FINISH_DURATION = 1.65;
const EXIT_CLIP_DELAY = 0.6;

class IntroLoadingPanel {
  private readonly _panel: HTMLElement | null;
  private readonly _percentValue: HTMLElement | null;

  constructor() {
    if (typeof document === "undefined") {
      this._panel = null;
      this._percentValue = null;
      return;
    }
    this._panel = document.querySelector<HTMLElement>(INTRO_PANEL_SELECTOR);
    this._percentValue = document.querySelector<HTMLElement>(
      INTRO_PERCENT_SELECTOR,
    );
  }

  reset(): void {
    this.show();
    this._setPercentText(0);
    this._progressBridge()?.reset?.();
  }

  show(): void {
    if (!this._panel) return;
    this._panel.style.opacity = "1";
    this._panel.style.transform = "translate3d(0, 0, 0) scale(1)";
    this._panel.style.clipPath = "inset(0 0 0 0)";
  }

  setProgress(progress: number): void {
    const clamped = Math.max(0, Math.min(100, progress));
    this._setPercentText(clamped);
    this._progressBridge()?.set?.(clamped);
  }

  private _setPercentText(progress: number): void {
    if (!this._percentValue) return;
    this._percentValue.textContent = `${Math.round(progress)}`;
  }

  private _progressBridge():
    | {
        reset?: () => void;
        set?: (value: number) => void;
      }
    | undefined {
    if (typeof window === "undefined") return undefined;
    return (
      window as Window & {
        __introProgress?: {
          reset?: () => void;
          set?: (value: number) => void;
        };
      }
    ).__introProgress;
  }
}

export async function runIntroLoadingProgress(
  loadPromise: Promise<void> | undefined,
  gsapApi: IntroRunContext["gsap"],
): Promise<void> {
  if (!loadPromise) return;
  const panel = new IntroLoadingPanel();
  panel.reset();
  let progress = 0;
  let isSettled = false;
  let frameId: number | null = null;
  const minDurationPromise = new Promise<void>((resolve) => {
    window.setTimeout(resolve, INTRO_PROGRESS_MIN_DURATION_MS);
  });
  const tick = (): void => {
    if (isSettled) return;
    progress = Math.min(
      INTRO_PROGRESS_HOLD_MAX,
      progress +
        Math.max(
          INTRO_PROGRESS_STEP_MIN,
          (INTRO_PROGRESS_HOLD_MAX - progress) * INTRO_PROGRESS_EASE,
        ),
    );
    panel.setProgress(progress);
    frameId = window.requestAnimationFrame(tick);
  };

  panel.setProgress(0);
  frameId = window.requestAnimationFrame(tick);
  try {
    await Promise.all([loadPromise, minDurationPromise]);
  } finally {
    isSettled = true;
    if (frameId !== null) window.cancelAnimationFrame(frameId);
  }

  if (!gsapApi) {
    panel.setProgress(100);
    return;
  }

  await new Promise<void>((resolve) => {
    const progressState = { value: progress };
    gsapApi.to(progressState, {
      value: 100,
      duration: INTRO_FINISH_DURATION,
      ease: "power2.out",
      onUpdate: () => panel.setProgress(progressState.value),
      onComplete: () => {
        panel.setProgress(100);
        resolve();
      },
    });
  });
}

export function runIntroDomTimeline(
  tl: GSAPTimeline,
  ctx?: IntroRunContext,
): GSAPTimeline {
  const loadPromise = ctx?.loadPromise;
  const panel = new IntroLoadingPanel();
  tl.addLabel("introEnter", 0);
  tl.add(() => panel.reset(), "introEnter");
  tl.addLabel("introProgressStart", "introEnter");

  if (loadPromise) {
    tl.add(
      () =>
        ctx?.controller?.runWaitPromise(
          runIntroLoadingProgress(loadPromise as Promise<void>, ctx?.gsap),
        ),
      "introProgressStart",
    );
  }

  tl.addLabel("introExit", ">").to(
    INTRO_PANEL_SELECTOR,
    {
      clipPath: "inset(0 0 100% 0)",
      duration: EXIT_CLIP_DELAY,
      ease: "power2.inOut",
    },
    "introExit",
  );
  return tl;
}

